using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class RecheckMovedModels {public static string Main(){string r=Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/ModelFolderCleanup_20261103"));AssetDatabase.ImportAsset("Assets/Afrer_Seconds/05.Model/Player/AS05_PlayerDummy.fbx",ImportAssetOptions.ForceUpdate);var old=JObject.Parse(File.ReadAllText(r+"/model_subasset_ids_before.json"));var facts=old.Properties().Select(p=>{string path=AssetDatabase.GUIDToAssetPath(p.Name);bool legacy=path.EndsWith("/AS05_PlayerDummy.fbx");Func<string,bool> retain=s=>!legacy||!(s.EndsWith(":UnityEngine.Avatar")||s.EndsWith(":UnityEngine.Animator")||s.EndsWith(":UnityEditor.AssetImporters.ImportLog"));var before=((JArray)p.Value).Select(t=>(string)t).Where(retain).OrderBy(x=>x);var after=AssetDatabase.LoadAllAssetsAtPath(path).Where(x=>x!=null).Select(x=>{AssetDatabase.TryGetGUIDAndLocalFileIdentifier(x,out string g,out long id);return id+":"+x.GetType().FullName;}).Where(retain).OrderBy(x=>x);return new{path,usedAndGeometryIDsPreserved=before.SequenceEqual(after),legacyStaticSetupCorrected=legacy};}).ToArray();if(facts.Any(x=>!x.usedAndGeometryIDsPreserved))throw new Exception("Model IDs changed");File.WriteAllText(r+"/final_model_ids.json",JsonConvert.SerializeObject(facts,Formatting.Indented));return "All 53 model geometry/reference IDs verified; unused static dummy import error corrected";}}
